if(packaging.electronFuses?.runAsNode!==true||!packaging.extraResources.some(item=>item.from==='native/system-media/build/system-media.exe'&&item.to==='system-media.exe')||!packaging.extraResources.some(item=>item.from==='native/media-worker/build/media-worker.exe'&&item.to==='media-worker.exe'))fail('media supervisor runtime/packaging contract differs');
