if(!association.includes('customInstall')||!association.includes('customUnInstall')||!association.includes('dev.aural.music.audio')||/WriteReg\w+\s+(HKLM|HKCR)\b/.test(association)||/WriteReg\w+[^\n]*UserChoice/.test(association))fail('unsafe Open With registration source');
const runtime = Object.entries(lock.packages)
  .filter(([location, record]) => location.startsWith('node_modules/') && !record.dev && !record.devOptional)
